test('useSelector returns correct initial slice', () => {
  const ctx = createSelectableContext({ count: 0, name: 'Alice' });
  const { result } = renderHook(
    () => ctx.useSelector(s => s.count),
    { wrapper: ({ children }) => <ctx.Provider value={{ count: 7, name: 'Bob' }}>{children}</ctx.Provider> }
  );
  expect(result.current).toBe(7);
});

test('useSelector updates when selected slice changes', () => {
  const ctx = createSelectableContext({ count: 0 });
  let value = { count: 0 };
  const { result, rerender } = renderHook(
    () => ctx.useSelector(s => s.count),
    { wrapper: ({ children }) => <ctx.Provider value={value}>{children}</ctx.Provider> }
  );
  value = { count: 5 };
  rerender();
  expect(result.current).toBe(5);
});

test('useSelector with identity selector returns full state', () => {
  const ctx = createSelectableContext({ x: 1, y: 2 });
  const { result } = renderHook(
    () => ctx.useSelector(s => s),
    { wrapper: ({ children }) => <ctx.Provider value={{ x: 1, y: 2 }}>{children}</ctx.Provider> }
  );
  expect(result.current).toEqual({ x: 1, y: 2 });
});

