solution:
import { createContext, useContext, useRef, useLayoutEffect, useSyncExternalStore, FC, ReactNode } from 'react';

export function createSelectableContext<T>(initial: T) {
  type Store = { getSnapshot: () => T; subscribe: (fn: () => void) => () => void; };

  const Context = createContext<Store>(null as any);

  const Provider: FC<{ value: T; children: ReactNode }> = ({ value, children }) => {
    const valueRef = useRef(value);
    const listeners = useRef(new Set<() => void>());

    valueRef.current = value;

    const store = useRef<Store>({
      getSnapshot: () => valueRef.current,
      subscribe: (fn) => {
        listeners.current.add(fn);
        return () => listeners.current.delete(fn);
      },
    });

    useLayoutEffect(() => {
      listeners.current.forEach(fn => fn());
    }, [value]);

    return <Context.Provider value={store.current}>{children}</Context.Provider>;
  };

  function useSelector<R>(selector: (v: T) => R): R {
    const store = useContext(Context);
    return useSyncExternalStore(
      store.subscribe,
      () => selector(store.getSnapshot())
    );
  }

  return { Provider, useSelector };
}
